import { useColorMode } from "@kobalte/core";
import type { Component, ComponentProps } from "solid-js";

import { Toaster as Sonner } from "solid-sonner";
import IconAlertLine from "~icons/ri/alert-line";
import IconCheckboxCircleLine from "~icons/ri/checkbox-circle-line";
import IconCloseCircleLine from "~icons/ri/close-circle-line";
import IconInformationLine from "~icons/ri/information-line";
import IconLoader4Line from "~icons/ri/loader-4-line";

type ToasterProps = ComponentProps<typeof Sonner>;

const Toaster: Component<ToasterProps> = (props) => {
  const { colorMode } = useColorMode();

  return (
    <Sonner
      theme={colorMode()}
      class="group toaster"
      icons={{
        success: (
          <IconCheckboxCircleLine
            class="size-4"
          />
        ),
        info: (
          <IconInformationLine
            class="size-4"
          />
        ),
        warning: (
          <IconAlertLine
            class="size-4"
          />
        ),
        error: (
          <IconCloseCircleLine
            class="size-4"
          />
        ),
        loading: (
          <IconLoader4Line
            class="size-4 animate-spin"
          />
        ),
      }}
      style={{
        "--normal-bg": "var(--popover)",
        "--normal-text": "var(--popover-foreground)",
        "--normal-border": "var(--border)",
        "--border-radius": "var(--radius)",
      }}
      toastOptions={{
        classes: {
          toast: "cn-toast",
        },
      }}
      {...props}
    />
  );
};

export { Toaster };
